import numpy as np

def r(x):
    # Apply a non-linear power transform that maps [0,1] to [0,1].
    # For x in [0,1], sqrt(x) >= x, ensuring the transformed input
    # is component-wise greater than or equal to the original.
    return np.sqrt(x)

def R(y_orig, y_new):
    # Verify that both outputs are finite numbers.
    # Non-finite values (NaN, Inf) indicate invalid computation.
    return np.isfinite(y_orig) and np.isfinite(y_new)
